node.status({fill:'green', shape:'dot', text:'tokens set'});
return null;

const orig = msg.originalMessage;
const from = orig.from || {};
const origMsg = orig.message || {};
const chatId = (origMsg.chat && origMsg.chat.id) ? origMsg.chat.id : msg.payload.chatId;
const token = global.get('telegram_token');
const callbackData = msg.payload.content;

// Store event data in msg.eventData to avoid JSONata 'payload' resolution issues
msg.eventData = {
    user_id: from.id,
    from_first: from.first_name || '',
    from_last: from.last_name || '',
    chat_id: chatId,
    callback_data: callbackData,
    message: {
        message_id: origMsg.message_id,
        chat_id: chatId,
        text: origMsg.text || ''
    }
};

// Output 2: answerCallbackQuery (clears button spinner)
const answerMsg = {
    url: `https://api.telegram.org/bot${token}/answerCallbackQuery`,
    headers: { 'Content-Type': 'application/json' },
    payload: { callback_query_id: orig.id }
};

node.status({fill:'purple', shape:'dot', text: callbackData});
return [msg, answerMsg];

const p = msg.payload;
const from = msg.originalMessage.from || {};

msg.payload = {
    id: p.messageId,
    chat_id: p.chatId,
    user_id: from.id,
    from_first: from.first_name || '',
    from_last: from.last_name || '',
    text: (typeof p.content === 'string') ? p.content : (p.content.text || ''),
    date: new Date().toISOString()
};

node.status({fill:'blue', shape:'dot', text: msg.payload.text.substring(0, 50)});
return msg;

const from = msg.originalMessage.from || {};

flow.set('voice_meta', {
    chatId: msg.payload.chatId,
    userId: from.id,
    firstName: from.first_name || '',
    lastName: from.last_name || '',
    messageId: msg.payload.messageId
});

const token = global.get('telegram_token');
node.status({fill:'yellow', shape:'ring', text:'transcribing...'});

// Newer library versions: content is a file_id string + weblink is pre-built
if (msg.payload.weblink) {
    msg.url = msg.payload.weblink;
    return [msg, null]; // skip getFile, go direct to download
}

// Older library versions: content is a voice object with file_id
const content = msg.payload.content;
const fileId = (typeof content === 'string') ? content
             : (content && content.file_id) ? content.file_id
             : (content && content.voice && content.voice.file_id) ? content.voice.file_id
             : null;
if (!fileId) {
    node.error('voice: cannot find file_id in payload', msg);
    return null;
}
msg.url = `https://api.telegram.org/bot${token}/getFile?file_id=${fileId}`;
return [null, msg]; // use getFile path

const token = global.get('telegram_token');
const filePath = msg.payload.result.file_path;

msg.url = `https://api.telegram.org/file/bot${token}/${filePath}`;
msg.method = 'GET';
return msg;

const audioBase64 = msg.payload.toString('base64');
const apiKey = global.get('gemini_api_key');
const model = global.get('gemini_model') || 'gemini-2.0-flash-lite';

msg.url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`;
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = {
    contents: [{
        parts: [
            {
                text: 'Transcribe this audio exactly as spoken in the original language. Return ONLY the transcribed text. No quotes, no explanation, no formatting.'
            },
            {
                inline_data: {
                    mime_type: 'audio/ogg',
                    data: audioBase64
                }
            }
        ]
    }]
};
return msg;

const text = msg.payload.candidates[0].content.parts[0].text.trim();
const meta = flow.get('voice_meta');

msg.payload = {
    id: meta.messageId,
    chat_id: meta.chatId,
    user_id: meta.userId,
    from_first: meta.firstName,
    from_last: meta.lastName,
    text: text,
    date: new Date().toISOString()
};

node.status({fill:'green', shape:'dot', text: text.substring(0, 50)});
return msg;

