function scheduleNext() {
    const interval = flow.get('watchdog_interval_ms') || 15 * 60 * 1000;
    const t = setTimeout(() => {
        node.send({ payload: {}, topic: 'probe' });
        scheduleNext();
    }, interval);
    context.set('timer', t);
}
scheduleNext();

