const token = global.get('telegram_token');
msg.url = `https://api.telegram.org/bot${token}/getUpdates?timeout=0&limit=1`;
msg.method = 'GET';
return msg;

const code = msg.statusCode;
let result;
if (code === 409) {
    result = 'healthy';
} else if (code === 200) {
    result = 'dead';
} else {
    result = 'unknown';
}
msg.probeResult = result;
return msg;

const FIFTEEN_MIN = 15 * 60 * 1000;
const HOUR = 60 * 60 * 1000;

const state = flow.get('watchdog_state') || 'ok';
const notified = flow.get('watchdog_notified') || false;
const probeResult = msg.probeResult;
const isReprobe = msg.topic === 'reprobe';

let next;
if (probeResult === 'unknown') {
    next = { state, notified, action: 'none', intervalMs: state === 'failed' ? HOUR : FIFTEEN_MIN };
} else if (!isReprobe) {
    if (probeResult === 'healthy') {
        next = { state: 'ok', notified: false, action: 'none', intervalMs: FIFTEEN_MIN };
    } else {
        next = { state: 'recovering', notified, action: 'recover', intervalMs: FIFTEEN_MIN };
    }
} else if (probeResult === 'healthy') {
    next = { state: 'ok', notified: false, action: 'notifyRecovered', intervalMs: FIFTEEN_MIN };
} else if (notified) {
    next = { state: 'failed', notified: true, action: 'none', intervalMs: HOUR };
} else {
    next = { state: 'failed', notified: true, action: 'notifyFailed', intervalMs: HOUR };
}

flow.set('watchdog_state', next.state);
flow.set('watchdog_notified', next.notified);
flow.set('watchdog_interval_ms', next.intervalMs);

node.status({ fill: next.state === 'ok' ? 'green' : (next.state === 'recovering' ? 'yellow' : 'red'), shape: 'dot', text: `${next.state} (${probeResult})` });

const recoverMsg = next.action === 'recover' ? msg : null;
const recoveredMsg = next.action === 'notifyRecovered' ? { payload: {} } : null;
const failedMsg = next.action === 'notifyFailed' ? { payload: {} } : null;
return [recoverMsg, recoveredMsg, failedMsg];

const flowDef = msg.payload;
const origNodes = flowDef.nodes;
msg.origNodes = origNodes;
msg.flowId = flowDef.id;
msg.flowLabel = flowDef.label;

const toggled = origNodes.map(n => n.id === 'tb_bot_cfg' ? Object.assign({}, n, { d: true }) : n);

msg.url = 'http://localhost:1880/flow/tb_flow';
msg.method = 'PUT';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { id: flowDef.id, label: flowDef.label, nodes: toggled };
return msg;

